from collections import deque

def topo_sort(graph):
    in_degree = {}
    adj = {}

    # Identify all unique nodes in the graph
    nodes = set(graph.keys())
    for dependencies in graph.values():
        nodes.update(dependencies)

    # Initialize in-degree and adjacency list for all nodes
    for node in nodes:
        in_degree[node] = 0
        adj[node] = []

    # Build the adjacency list (dependency -> node) and calculate in-degrees
    for node, dependencies in graph.items():
        for dep in dependencies:
            adj[dep].append(node)
            in_degree[node] += 1

    # Kahn's Algorithm: Start with nodes that have no dependencies
    queue = deque([node for node in nodes if in_degree[node] == 0])
    result = []

    while queue:
        u = queue.popleft()
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # If result contains all nodes, return it; otherwise, a cycle exists
    return result if len(result) == len(nodes) else None
```

