from urllib.parse import unquote_plus

def parse_query(qs):
    result = {}
    if not qs:
        return result

    for pair in qs.split('&'):
        if not pair:
            continue

        parts = pair.split('=', 1)
        key = unquote_plus(parts[0])
        val = unquote_plus(parts[1]) if len(parts) > 1 else ""

        if key in result:
            if isinstance(result[key], list):
                result[key].append(val)
            else:
                result[key] = [result[key], val]
        else:
            result[key] = val

    return result
