import re

def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Invalid duration string")

    pattern = r'(\d+)([dhms])'
    matches = re.findall(pattern, s)

    # Ensure the entire string is consumed by the matches to prevent invalid inputs
    if "".join(m[0] + m[1] for m in matches) != s:
        raise ValueError(f"Invalid duration string: {s}")

    units = {
        'd': 86400,
        'h': 3600,
        'm': 60,
        's': 1
    }

    return sum(int(val) * units[unit] for val, unit in matches)
```

