def strip_comments(code):
    result = []
    in_string = None
    escaped = False
    i = 0
    while i < len(code):
        char = code[i]

        if escaped:
            result.append(char)
            escaped = False
        elif char == '\\':
            result.append(char)
            escaped = True
        elif in_string:
            result.append(char)
            if char == in_string:
                in_string = None
        elif char == '#':
            # Find the end of the line to skip the comment
            while i < len(code) and code[i] != '\n':
                i += 1
            continue
        elif char in ("'", '"'):
            in_string = char
            result.append(char)
        else:
            result.append(char)

        i += 1

    return "".join(result)
```

