import re

def mask_secrets(text):
    def replacer(match):
        key = match.group(1)
        if any(secret in key.lower() for secret in ['password', 'token', 'key']):
            return f"{key}=***"
        return match.group(0)

    # Matches key=value where key is alphanumeric/underscore and value is non-whitespace/non-comma
    return re.sub(r'(\w+)=([^,\s]*)', replacer, text)
