function debounceCount(fn, ms) {
  let timer = null;
  let context = null;
  let args = null;

  const call = function(...newArgs) {
    context = this;
    args = newArgs;

    if (timer) {
      clearTimeout(timer);
    }

    timer = setTimeout(() => {
      fn.apply(context, args);
      timer = null;
      context = null;
      args = null;
    }, ms);
  };

  const flush = function() {
    if (timer) {
      clearTimeout(timer);
      fn.apply(context, args);
      timer = null;
      context = null;
      args = null;
    }
  };

  return {
    call,
    flush
  };
}

module.exports = debounceCount;
```

