function rotateArray(arr, k) {
  const n = arr.length;
  if (n === 0) return [];

  let shift = k % n;
  if (shift < 0) {
    shift += n;
  }

  if (shift === 0) {
    return [...arr];
  }

  const rightPart = arr.slice(-shift);
  const leftPart = arr.slice(0, n - shift);

  return [...rightPart, ...leftPart];
}

module.exports = rotateArray;
```

