export function maxBy<T>(arr: T[], f: (t: T) => number): T | undefined {
  if (arr.length === 0) {
    return undefined;
  }

  let maxElement = arr[0];
  let maxValue = f(maxElement);

  for (let i = 1; i < arr.length; i++) {
    const current = arr[i];
    const val = f(current);
    if (val > maxValue) {
      maxValue = val;
      maxElement = current;
    }
  }

  return maxElement;
}
