// unless props change.
const ChildComponent = memo(({ onPress }) => {
  console.log('ChildComponent rendered');
  return (
    <TouchableOpacity style={styles.button} onPress={onPress}>
      <Text style={styles.text}>Stable Identity Button</Text>
    </TouchableOpacity>
