const MutableValueComponent = () => {
  const [renderCount, setRenderCount] = useState(0);

  // This value persists across renders but changing it does NOT trigger a re-render
  const mutableValue = useRef(0);

  const incrementRef = () => {
    mutableValue.current += 1;
    console.log('Current Ref Value:', mutableValue.current);
  };

  const triggerReRender = () => {
    setRenderCount(prev => prev + 1);
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>useRef Demonstration</Text>

      <View style={styles.card}>
        <Text style={styles.label}>State (Triggers Re-render):</Text>
        <Text style={styles.value}>{renderCount}</Text>
      </View>

      <View style={styles.card}>
        <Text style={styles.label}>Ref (Mutable, No Re-render):</Text>
        <Text style={styles.value}>{mutableValue.current}</Text>
